"""Reviewed serverless GPU/credit comparisons; no provisioning or account operations."""
from html import escape as E


def summary(data):
 return '<aside class="classroom50-summary"><p class="pg-kicker">Modal and similar platforms · checked October 16, 2026</p><h2>A free plan is not free class capacity.</h2><p>'+E(data['serverless_assessment']['verdict'])+'</p><p><a href="serverless-compute.html">Compare nine platforms, billing boundaries and DS/MLIS work ↗</a></p></aside>'


def estimates(data):
 r=data['serverless_assessment']['modal_rates'];base=r['physical_cores']*r['cpu_physical_core_per_second']+r['memory_gib']*r['memory_gib_per_second']
 return [(name,(rate+base)*3600,r['credit']/((rate+base)*3600)) for name,rate in [('T4',r['t4_per_second']),('H100',r['h100_per_second'])]]


def view(data):
 a=data['serverless_assessment'];e=data['evidence']
 cards=''.join('<article class="pg-card" id="platform-'+E(r['id'])+'"><p class="pg-kicker">'+E(r['kind'])+'</p><h3>'+E(r['name'])+'</h3><p><strong>'+E(r['allowance'])+'</strong></p><p>'+E(r['work'])+'</p><p>'+E(r['fit'])+'</p><p class="pg-note warning">'+E(r['limits'])+'</p><p class="pg-refs">'+ ' · '.join('<a href="evidence.html#'+k+'">'+E(e[k]['title'])+'</a>' for k in r['sources'])+'</p></article>' for r in a['platforms'])
 example=''.join('<tr><th scope="row">'+name+'</th><td>$'+f'{cost:.3f}'+'/hour</td><td>≈ '+f'{hours:.1f}'+' hours/month</td></tr>' for name,cost,hours in estimates(data))
 return '''<p class="pg-kicker">Commercial compute alternatives · documentary assessment</p><h1>Small credits.<br>Useful experiments.</h1><p class="pg-lead">'''+E(a['verdict'])+'''</p><div class="pg-actions"><a class="pg-link primary" href="https://modal.com/pricing">Modal pricing ↗</a><a class="pg-link" href="#comparison">Compare nine platforms ↓</a><a class="pg-link" href="gpu-benchmark.html">Current benchmark materials ↗</a></div><p class="pg-note">'''+E(a['status'])+''' Earlier provider records keep their own dates. These services are externally operated; account credits do not establish institutional control or semester capacity.</p><section id="modal"><p class="pg-kicker">Modal: promising, with conditions</p><h2>Separate credits, seats and charges.</h2><div class="classroom50-flow"><div><span>Compute allowance</span><strong>$30 per workspace/month</strong><p>CPU, memory and GPU share the allowance. Standard Functions, Sandboxes and Notebooks have different rates.</p></div><div><span>People and parallel work</span><strong>3 seats · 10 concurrent GPUs</strong><p>Starter limits are not an 80-student roster, an award, or a simultaneous-class reservation.</p></div><div><span>Billing boundary</span><strong>Payment method required</strong><p>Set a usage budget and a separate net-charge spend limit. No personal/student card or purchase is proposed.</p></div></div><p class="pg-note warning"><strong>Shared Endpoints are separate:</strong> Modal’s pricing FAQ says token usage is billed from the first request and excluded from the $30 compute allowance, effective September 1, 2026. Free access to compute does not mean free access to every model API.</p><p><a href="https://modal.com/academics">Academic credit grants</a> are worth assessing: Modal advertises up to $10,000 for graduate students, labs and researchers. Course-wide eligibility, credit expiry, payment exceptions, seat access and product coverage need written confirmation. No application or award is implied; ACCESS remains the classroom CPU/GPU route.</p><div class="pg-table"><table><thead><tr><th>Illustrative Function GPU</th><th>GPU + 2 physical CPU cores + 8 GiB memory</th><th>$30 divided by that rate</th></tr></thead><tbody>'''+example+'''</tbody></table></div><p class="pg-small">Arithmetic illustration from October 16 list rates, not a benchmark, quote or awarded capacity. Physical cores are not vCPU counts. Assumes the whole monthly compute credit is available; excludes build/start/warm overhead, extra usage, storage/egress charges and region/non-preemptible multipliers. Sandbox/Notebook CPU and memory pricing differs. Real useful runtime will be lower when those costs apply.</p></section><section id="comparison"><p class="pg-kicker">Nine distinct fits</p><h2>Choose the work, then check the account.</h2><p>Recurring credits, bounded shared machines, promotional trials, unconfirmed offers and paid model APIs serve different purposes. No signup or payment test was performed.</p><div class="pg-grid">'''+cards+'''</div></section><section id="course-fit"><h2>What DS and MLIS could do.</h2><div class="pg-grid"><article class="pg-card"><h3>Data science</h3><p>Prepare/debug on CPU. For an authorized Modal test, package a small fixed-data training or inference function; record GPU type, cold/warm wall time, correctness, checkpoints and total charged CPU/memory/GPU usage.</p><p>General training needs a custom runtime, not only access to a provider’s model API. Keep the existing Kaggle/Colab notebooks and final ACCESS replay as the baseline.</p></article><article class="pg-card"><h3>Library and information science</h3><p>Test rights-cleared public/synthetic OCR, document embeddings, metadata suggestions or retrieval. Separate model/API quality from the performance of our own code. Private holdings, patron data and course records need approved destinations.</p><p>Existing MLIS GPU code measures a projection/retrieval proxy; it is not a pretrained embedding or OCR quality benchmark. Checkpoint and export outputs; vendor storage is not a preservation repository.</p></article></div></section><section><h2>Before any cloud canary.</h2><ol class="pg-checklist">'''+''.join('<li>'+E(c)+'</li>' for c in a['checks'])+'''</ol><p class="pg-note">Zero cash budget. TA, course-lead and technical support commitments need confirmation. No new staffing costs or paid fallback are assumed. Campus AWS stays CPU component-testing only; all thirteen classroom gates remain planned.</p></section><section><h2>Evidence and unresolved offers.</h2><p>Direct pricing tables take precedence over older snippets: Beam’s current Developer plan is paid despite an older free-credit comparison. Hugging Face Free-account Inference Providers currently includes no monthly credit; its ZeroGPU/Spaces allowance is a separate product. Saturn’s 150-hour landing claim remains unconfirmed against current pricing/account access. Paperspace’s free machine timer is six hours, despite a generic 12-hour marketing timer.</p><p class="pg-small">'''+E(a['methods'])+'''</p><div class="pg-actions"><a class="pg-link" href="evidence.html#modalpricing">Source ledger ↗</a><a class="pg-link" href="research-report.html">Full report ↗</a><a class="pg-link" href="classroom-resources.html">All resource comparisons ↗</a></div></section>'''


def report_text(data):
 a=data['serverless_assessment'];e=data['evidence']
 text='\n\nMODAL AND SIMILAR COMPUTE PLATFORMS | October 16, 2026\n\n'+a['verdict']+'\n'+a['status']+'\n\n'
 for r in a['platforms']:text+=r['name'].upper()+' | '+r['kind']+'\n'+r['allowance']+'\n'+r['work']+'\n'+r['fit']+'\nBoundary: '+r['limits']+'\n\n'
 text+='MODAL RATE ILLUSTRATION (NOT MEASURED)\nStandard Functions, 2 physical CPU cores and 8 GiB memory; the full $30 monthly allowance is available. Excludes startup/warm overhead, other usage, storage/egress and region/execution multipliers. Not the Sandbox/Notebook CPU rate.\n'
 for n,c,h in estimates(data):text+=f'{n}: ${c:.6f}/hour; approximately {h:.1f} hours from $30 before excluded costs.\n'
 text+='\nBEFORE AN AUTHORIZED CLOUD CANARY (NOT RUN)\n'+'\n'.join(str(i+1)+'. '+c for i,c in enumerate(a['checks']))+'\n\nRESEARCH METHOD AND CONFLICTS\n'+a['methods']+'\nBeam direct pricing overrides the earlier free-$30 blog; do not invent an effective change date. Saturn device-specific free entitlement and new-account access remain unconfirmed. Paperspace free machine session guidance overrides the generic marketing timer. HF API pricing does not describe ZeroGPU.\n\nPRIMARY SOURCES FOR THE COMMERCIAL COMPUTE EXTENSION\n'
 for k in dict.fromkeys(k for r in a['platforms'] for k in r['sources']):text+='\n'+e[k]['title']+'\n'+e[k]['claim']+'\nScope: '+e[k]['scope']+'\n'+e[k]['url']+'\n'
 return text
